{"policy":"permit (
    principal,
    action == Action::"clearSecurityCheck",
    resource
)
when {
    principal.roles.contains(Role::"BackgroundInvestigator") &&
    resource.status == "pending" &&
    context.currentTime >= resource.permittedWindowStart &&
    context.currentTime <= resource.permittedWindowEnd
};

permit (
    principal,
    action == Action::"clearSecurityCheck",
    resource
)
when {
    principal.roles.contains(Role::"SupervisoryOfficer") &&
    context.currentTime >= resource.permittedWindowStart &&
    context.currentTime <= resource.permittedWindowEnd
};

forbid (
    principal,
    action == Action::"clearSecurityCheck",
    resource
)
when {
    principal.roles.contains(Role::"BackgroundInvestigator") &&
    resource.status != "pending"
};

forbid (
    principal,
    action == Action::"clearSecurityCheck",
    resource
)
when {
    (principal.roles.contains(Role::"BackgroundInvestigator") ||
     principal.roles.contains(Role::"SupervisoryOfficer")) &&
    (context.currentTime < resource.permittedWindowStart ||
     context.currentTime > resource.permittedWindowEnd)
};"}
